for rec in records.get('item_fee', []):
    vals = rec['values']
    item_fee[vals['item_ref']] = int(vals['activation_fee_cents'])
category_ids = set()
cat_minq = {}
cat_maxq = {}
cat_actfee = {}
for rec in records.get('category', []):
    vals = rec['values']
    cat = vals['category']
    category_ids.add(cat)
    cat_minq[cat] = int(vals['minimum_quantity'])
    cat_maxq[cat] = int(vals['maximum_quantity'])
    cat_actfee[cat] = int(vals['activation_fee_cents'])
resource_ids = set()
cap_resource = {}
for rec in records.get('capacity_ledger', []):
    vals = rec['values']
    res = vals['resource']
    resource_ids.add(res)
    cap_resource[res] = cap_resource.get(res, 0.0) + float(vals['amount'])
usage = {i: {r: 0.0 for r in resource_ids} for i in item_ids}
for rec in records.get('usage', []):
    vals = rec['values']
    ref = vals['item_ref']
    res = vals['resource']
    usage[ref][res] = float(vals['amount'])
fx = {}
for rec in records.get('fx', []):
    vals = rec['values']
    cur = vals['currency']
    fx[cur] = (float(vals['usd_cents_numerator']), float(vals['denominator']))
benefit_per_unit = {i: 0.0 for i in item_ids}
for rec in records.get('benefit', []):
    vals = rec['values']
    ref = vals['item_ref']
    amt = float(vals['amount'])
    cur = vals['currency']
    num, den = fx[cur]
    benefit_per_unit[ref] += amt * num / den
bundle_ids = []
bundle_items = {}
bundle_bonus = {}
for rec in records.get('bundle', []):
    vals = rec['values']
    bid = (vals['item_a'], vals['item_b'])
    bundle_ids.append(bid)
    bundle_items[bid] = (vals['item_a'], vals['item_b'])
    bundle_bonus[bid] = int(vals['bonus_cents'])
incompat_pairs = []
for rec in records.get('incompatible', []):
    vals = rec['values']
    incompat_pairs.append((vals['item_a'], vals['item_b']))
requires_pairs = []
for rec in records.get('requires', []):
    vals = rec['values']
    requires_pairs.append((vals['item_ref'], vals['prerequisite_ref']))
quantity = {i: m.addVar(vtype=GRB.INTEGER, name=f'q_{i}') for i in item_ids}
selected = {i: m.addVar(vtype=GRB.BINARY, name=f'z_{i}') for i in item_ids}
category_active = {c: m.addVar(vtype=GRB.BINARY, name=f'w_{c}') for c in category_ids}
bundle_active = {b: m.addVar(vtype=GRB.BINARY, name=f'b_{b[0]}_{b[1]}') for b in bundle_ids}
max_order = max((item_maxord[i] for i in item_ids if item_authorized[i] == 1))
M = max_order
for i in item_ids:
    auth = item_authorized[i]
    minlot = item_minlot[i]
    maxord = item_maxord[i]
    m.addConstr(selected[i] <= auth)
    m.addConstr(quantity[i] <= auth * maxord)
    m.addConstr(quantity[i] >= minlot * selected[i])
    m.addConstr(quantity[i] <= M * selected[i])
for c in category_ids:
    items_in_cat = [i for i in item_ids if item_category[i] == c]
    m.addConstr(gurobipy.quicksum((quantity[i] for i in items_in_cat)) >= cat_minq[c] * category_active[c])
    m.addConstr(gurobipy.quicksum((quantity[i] for i in items_in_cat)) <= cat_maxq[c] * category_active[c])
for r in resource_ids:
    m.addConstr(gurobipy.quicksum((usage[i][r] * quantity[i] for i in item_ids)) <= cap_resource[r])
for i, j in incompat_pairs:
    if i in selected and j in selected:
        m.addConstr(selected[i] + selected[j] <= 1)
for i, j in requires_pairs:
    if i in selected and j in selected:
        m.addConstr(selected[i] <= selected[j])
for b in bundle_ids:
    a, b_item = bundle_items[b]
    if a in selected and b_item in selected:
        m.addConstr(bundle_active[b] <= selected[a])
        m.addConstr(bundle_active[b] <= selected[b_item])
        m.addConstr(bundle_active[b] >= selected[a] + selected[b_item] - 1)
obj = gurobipy.quicksum((benefit_per_unit[i] * quantity[i] for i in item_ids))
obj -= gurobipy.quicksum((item_fee.get(i, 0) * selected[i] for i in item_ids))
obj -= gurobipy.quicksum((cat_actfee[c] * category_active[c] for c in category_ids))
obj += gurobipy.quicksum((bundle_bonus[b] * bundle_active[b] for b in bundle_ids))
m.setObjective(obj, GRB.MAXIMIZE)
m.optimize()
